"""The zone table the device reads (`web/src/phone/zoneCountries.json`) is generated by
`scripts/phone/zone_countries.py` from the installed tzdata, and only by it."""

import json

import pytest

from app.shared.phone_country import PhoneCountry, listed_countries
from scripts.phone import zone_countries as generator

LISTED = [country.value for country in listed_countries()]


def committed(path_name: str) -> dict[str, object]:
    path = generator.ZONES_FILE if path_name == "zones" else generator.CODES_FILE
    document: dict[str, object] = json.loads(path.read_text(encoding="utf-8"))
    return document


def zones() -> dict[str, str]:
    table = committed("zones")["zones"]
    assert isinstance(table, dict)
    return table


def tzdata_zones_of_the_eight() -> set[str]:
    """Every zone of `zone.tab` (one country per line) whose country is listed."""
    found: set[str] = set()
    text = generator.read_tzdata("zone.tab")
    assert text is not None
    for line in text.splitlines():
        if line.startswith("#") or not line.strip():
            continue
        fields = line.split("\t")
        if fields[0] in LISTED:
            found.add(fields[2])
    return found


def test_every_tzdata_zone_of_the_eight_is_in_the_table() -> None:
    assert tzdata_zones_of_the_eight() - set(zones()) == set()


def test_every_value_is_a_listed_phone_country() -> None:
    assert {PhoneCountry(code) for code in zones().values()} <= set(PhoneCountry)


@pytest.mark.parametrize(
    ("zone", "code"),
    [
        ("America/Argentina/Buenos_Aires", "AR"),
        ("America/Montevideo", "UY"),
        ("America/Santiago", "CL"),
        ("America/Asuncion", "PY"),
        ("America/Sao_Paulo", "BR"),
        ("America/Mexico_City", "MX"),
        ("Europe/Madrid", "ES"),
        ("America/New_York", "US"),
        ("America/Buenos_Aires", "AR"),
        ("US/Pacific", "US"),
        ("Brazil/East", "BR"),
        ("Mexico/General", "MX"),
        ("Chile/Continental", "CL"),
        ("Navajo", "US"),
    ],
)
def test_the_zones_the_devices_of_the_eight_report(zone: str, code: str) -> None:
    assert zones()[zone] == code


def test_a_zone_outside_the_eight_is_not_in_the_table() -> None:
    assert "Europe/Paris" not in zones()


def test_a_line_that_lists_two_of_the_eight_is_refused_naming_the_zone_and_both_codes() -> None:
    line = "AR,UY\t-3436-05827\tAmerica/Foo\n"

    with pytest.raises(generator.AmbiguousZone) as refusal:
        generator.zones_of_tab(line, LISTED)

    assert str(refusal.value) == "America/Foo lists both AR and UY; add it to the alias list"


def test_an_aliased_zone_that_lists_two_of_the_eight_takes_the_first() -> None:
    line = "US,AR\t+0000+00000\tAmerica/Indianapolis\n"

    assert generator.zones_of_tab(line, LISTED) == {"America/Indianapolis": "US"}


def test_a_listed_country_after_an_unlisted_one_still_maps() -> None:
    assert generator.zones_of_tab("US,CA\t+3\tAmerica/Phoenix\n", LISTED) == {
        "America/Phoenix": "US"
    }


def test_the_committed_files_equal_a_fresh_regeneration_byte_for_byte() -> None:
    for path, text in generator.documents().items():
        assert path.read_text(encoding="utf-8") == text


def test_both_files_say_which_script_generated_them() -> None:
    assert committed("zones")["generated_by"] == "scripts/phone/zone_countries.py"
    assert committed("codes")["generated_by"] == "scripts/phone/zone_countries.py"


def test_the_listed_codes_are_the_listed_countries_in_their_order() -> None:
    assert committed("codes")["codes"] == [country.value for country in listed_countries()]
